/** Resolve the official logo for any built-in, preset, or custom provider ID / URL / label. */
export function ProviderLogo({
  id,
  providerId,
  label,
  baseUrl,
  size = 18,
  className,
}: {
  id?: string;
  providerId?: string;
  label?: string;
  baseUrl?: string;
  size?: number;
  className?: string;
}) {
  const haystack = `${providerId ?? id ?? ""} ${label ?? ""} ${baseUrl ?? ""}`.toLowerCase();
  if (haystack.includes("gemini") || haystack.includes("generativelanguage.googleapis")) {
    return <GeminiLogo size={size} className={className} />;
  }
  if (haystack.includes("claude") || haystack.includes("anthropic")) {
    return <ClaudeLogo size={size} className={className} />;
  }
  if (haystack.includes("azure") || haystack.includes("openai.azure.com")) {
    return <AzureLogo size={size} className={className} />;
  }
  if (haystack.includes("openai") || /\boai\b/.test(haystack)) {
    return <OpenAILogo size={size} className={className} />;
  }
  if (haystack.includes("nvidia") || haystack.includes("nim")) {
    return <NvidiaLogo size={size} className={className} />;
  }
  if (haystack.includes("openrouter")) {
    return <OpenRouterLogo size={size} className={className} />;
  }
  if (haystack.includes("opencode")) {
    return <OpenCodeLogo size={size} className={className} />;
  }
  if (haystack.includes("blackbox")) {
    return <BlackboxLogo size={size} className={className} />;
  }
  if (haystack.includes("llamacpp") || haystack.includes("llama.cpp")) {
    return <LlamaCppLogo size={size} className={className} />;
  }
  if (haystack.includes("ollama")) {
    return <OllamaLogo size={size} className={className} />;
  }
  if (haystack.includes("groq")) {
    return <GroqLogo size={size} className={className} />;
  }
  if (haystack.includes("deepseek")) {
    return <DeepSeekLogo size={size} className={className} />;
  }
  if (haystack.includes("mistral")) {
    return <MistralLogo size={size} className={className} />;
  }
  if (haystack.includes("together")) {
    return <TogetherLogo size={size} className={className} />;
  }
  if (haystack.includes("fireworks")) {
    return <FireworksLogo size={size} className={className} />;
  }
  if (/\bxai\b|api\.x\.ai|\bgrok\b/.test(haystack)) {
    return <XAILogo size={size} className={className} />;
  }
  if (haystack.includes("cerebras")) {
    return <CerebrasLogo size={size} className={className} />;
  }
  if (haystack.includes("perplexity")) {
    return <PerplexityLogo size={size} className={className} />;
  }
  if (haystack.includes("cohere")) {
    return <CohereLogo size={size} className={className} />;
  }
  if (haystack.includes("huggingface") || haystack.includes("hf.co")) {
    return <HuggingFaceLogo size={size} className={className} />;
  }
  if (haystack.includes("lmstudio") || haystack.includes("lm-studio") || haystack.includes("lm studio") || haystack.includes(":1234")) {
    return <LMStudioLogo size={size} className={className} />;
  }
  if (haystack.includes("moonshot") || haystack.includes("kimi")) {
    return <MoonshotLogo size={size} className={className} />;
  }
  if (haystack.includes("siliconflow") || haystack.includes("siliconcloud")) {
    return <SiliconFlowLogo size={size} className={className} />;
  }
  if (haystack.includes("deepinfra")) {
    return <DeepInfraLogo size={size} className={className} />;
  }
  if (haystack.includes("sambanova")) {
    return <SambaNovaLogo size={size} className={className} />;
  }
  if (haystack.includes("vllm")) {
    return <VllmLogo size={size} className={className} />;
  }
  if (haystack.includes("nebius")) {
    return <NebiusLogo size={size} className={className} />;
  }
  return <CustomServerLogo size={size} className={className} />;
}
